import { type } from '../../../shared/utility/utilityHelpers';
export const ActionTypes = {
  GET_CONTACT_US_COUNT: type('[ContactUsLayout] Get Contact Us Count'),
  GET_CONTACT_US_COUNT_SUCCESS: type('[ContactUsLayout] Get Contact Us Success'),
  GET_CONTACT_US_COUNT_FAIL: type('[ContactUsLayout] Get Contact Us Fail')
};
/* Get Customer Count Actions */

export class GetContactUsCountAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.GET_CONTACT_US_COUNT;
  }

}
export class GetContactUsCountSuccessAction {
  constructor(payload) {
    this.payload = payload;
    this.type = ActionTypes.GET_CONTACT_US_COUNT_SUCCESS;
  }

}
export class GetContactUsCountFailAction {
  constructor(payload = null) {
    this.payload = payload;
    this.type = ActionTypes.GET_CONTACT_US_COUNT_FAIL;
  }

}
